if(action==='purchase'){if(d.id){const index=state.purchases.findIndex(p=>+p.id===+d.id);if(index<0)throw Error('Purchase not found.');const old=state.purchases[index];if(!inYear(old.purchase_date)||!inYear(d.purchase_date))throw Error('Select the original purchase financial year.');if(+old.vehicle_id!==+d.vehicle_id)throw Error('The purchase vehicle cannot be changed.');if(state.sales.some(s=>+s.vehicle_id===+old.vehicle_id&&s.sale_date<d.purchase_date)||state.expenses.some(e=>+e.vehicle_id===+old.vehicle_id&&e.expense_date<d.purchase_date))throw Error('Purchase date cannot be after an existing sale or expense bill.');state.purchases[index]={...old,...d,id:old.id};if(Array.isArray(state.yard_expenses))for(const y of state.yard_expenses)if(+y.legacy_purchase_id===+old.id&&!y.release_date)y.cost_date=d.purchase_date;}else{if(state.purchases.some(x=>+x.vehicle_id===+d.vehicle_id))throw Error('This vehicle already has a purchase.');state.purchases.unshift({...d,yard_id:null,yard_expense:0,id:n})}}
