function validateExpenseBillRows(bills,purchaseDate){
 if(!Array.isArray(bills)||bills.length<1||bills.length>100)throw Error('Add between 1 and 100 bill rows.');
 const seen=new Set();
 for(const [index,bill] of bills.entries()){
  const no=String(bill.bill_no??'').trim().toUpperCase(),date=String(bill.bill_date??'');
  if(!no||no.length>100)throw Error('Enter a bill number of up to 100 characters on row '+(index+1)+'.');
  if(seen.has(no))throw Error('Bill number '+no+' is repeated. Every row needs a unique bill number.');seen.add(no);
  const parsedDate=new Date(date+'T00:00:00Z');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(parsedDate.getTime())||parsedDate.toISOString().slice(0,10)!==date)throw Error('Enter a valid bill date on row '+(index+1)+'.');
  if(purchaseDate&&date<=purchaseDate)throw Error('Date of bill on row '+(index+1)+' must be later than the vehicle purchase date ('+purchaseDate+').');
  if(!/^\d+$/.test(String(bill.party_id??''))||Number(bill.party_id)<1)throw Error('Select a party name on row '+(index+1)+'.');
  if(!String(bill.name??'').trim()||String(bill.name).trim().length>200)throw Error('Enter an item name of up to 200 characters on row '+(index+1)+'.');
  if(!/^\d{1,10}(\.\d{1,2})?$/.test(String(bill.total??'')))throw Error('Enter a valid bill amount on row '+(index+1)+'.');
 }
}
let expenseBillSequence=0;
function updateExpensePurchaseDate(form){
 const purchase=state.purchases.find(p=>+p.vehicle_id===+form.elements.vehicle_id.value),date=purchase?.purchase_date||'';
 const display=$('#expense-purchase-date',form);if(display)display.value=date;
 const hint=$('#expense-purchase-hint',form);if(hint)hint.textContent=date?'Bill dates must be later than '+date+'.':'Select a vehicle to see its purchase date.';
 let minimum=workspace?.financial_year.start||'';
 if(date){const next=new Date(date+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+1);minimum=[minimum,next.toISOString().slice(0,10)].sort().pop();}
 $$('[data-bill-row]',form).forEach(row=>{const input=$('[data-bill-date]',row),message=date&&input.value&&input.value<=date?'Date of bill must be later than purchase date '+date+'.':'';input.min=minimum;input.max=workspace?.financial_year.end||'';input.setCustomValidity(message);input.setAttribute('aria-invalid',message?'true':'false');$('[data-bill-date-error]',row).textContent=message;});
}
