function detail(id){const r=ledger().find(x=>+x.vehicle_id===+id);if(!r)return;const docs=state.documents.filter(x=>+x.vehicle_id===+id);const {layer}=modal('Vehicle ledger','The complete financial picture for this vehicle.',`<div class="detailhero"><span class="carthumb">${icon('car')}</span><div><h2>${esc(r.vehicle.name)}</h2><p>${esc(r.vehicle.details)}</p><span class="pill ${r.sale?'':'amber'}">${r.status}</span></div></div><div class="formgrid"><div><small class="subtitle">PURCHASED ON</small><p>${esc(r.purchase_date)}</p></div><div><small class="subtitle">BANK / PORTAL</small><p>${esc(m(r.bank_id).name)} / ${esc(m(r.portal_id).name)}</p></div><div><small class="subtitle">YARD</small><p>${esc(yardRows().filter(y=>+y.vehicle_id===+r.vehicle_id).map(y=>m(y.yard_id).name).filter(name=>name!=='—').join(', ')||'—')}</p></div><div><small class="subtitle">MANAGER</small><p>${esc(r.manager_name)}<br>${esc(r.manager_contact)}</p></div></div><div class="summarybox">${[['Purchase amount',r.amount],['Yard expenses',r.yard_expense],['Post-purchase bills',r.expenses],['Total vehicle cost',r.cost],...(r.sale?[['Sale amount',r.sale.amount],['Sale expenses',r.sale.sale_expense],['Net sales',r.sale.amount-r.sale.sale_expense],['Net profit',r.profit]]:[])].map(([l,v],i)=>`<div class="summaryrow ${l==='Net profit'?'total':''}"><span>${l}</span><b>${rupees(v)}</b></div>`).join('')}</div><div class="items"><h3>Expense bills</h3>${table(['Bill no.','Party','Total'],state.expenses.filter(x=>+x.vehicle_id===+id).map(x=>[esc(x.bill_no),esc(m(x.party_id).name),rupees(state.expense_items.filter(i=>+i.expense_id===+x.id).reduce((a,i)=>a+Number(i.total),0))]))}<h3>Documents</h3>${docs.map(d=>`<p><button class="textlink" data-download="${d.id}">${esc(m(d.document_id).name)} · ${esc(d.original_name)} ↓</button></p>`).join('')||'<p class="subtitle">No documents uploaded yet.</p>'}</div>`,true);$$('[data-download]',layer).forEach(b=>b.onclick=()=>download(b.dataset.download))}
