function yardExportRows(){return [['Vehicle','Yard name','Release date','Cost date','Yard expenses (INR)'],...yardRows().filter(y=>inYear(y.cost_date)).map(y=>[m(y.vehicle_id).name,m(y.yard_id).name,y.release_date||'Not recorded',y.cost_date,Number(y.amount)])]}



function resetUserPassword(target){
 if(!can('user')||!target)return;
 const {layer,close}=modal('Reset password',workspace.company_name+' · '+target.username+' · '+target.role,`<form><div class="formgrid">${field('New password (12–72 characters)','password','password')}${field('Confirm new password','confirm_password','password')}</div><label><input type="checkbox" data-show-password> Show passwords</label><div class="error" role="alert"></div><div class="formfooter"><button type="submit" class="btn primary">Reset password</button></div></form>`);
 const form=$('form',layer),password=form.elements.password,confirmation=form.elements.confirm_password;
 password.maxLength=72;confirmation.maxLength=72;
 $('[data-show-password]',form).onchange=e=>{password.type=confirmation.type=e.target.checked?'text':'password'};
 form.onsubmit=async e=>{e.preventDefault();const button=$('[type=submit]',form);button.disabled=true;try{
  if(password.value!==confirmation.value)throw Error('Passwords do not match.');
  if(new TextEncoder().encode(password.value).length>72)throw Error('Password must be no more than 72 bytes.');
  await request('reset_user_password',{id:target.id,password:password.value,confirm_password:confirmation.value});password.value=confirmation.value='';await refresh();close();render();toast('Password reset successfully for '+target.username);
 }catch(err){$('.error',form).textContent=err.message}finally{button.disabled=false}};
}
